argv:
$ErrorActionPreference='SilentlyContinue';
$paths=@('E:\WebAIBridge','E:\WebAIBridge\app','E:\web-ai-bridge','E:\web-ai-bridge\app');
$roots=@();
foreach($p in $paths){
 if(Test-Path $p){
  $roots += [pscustomobject]@{
   path=$p;
   git=(Test-Path (Join-Path $p '.git'));
   files=@(Get-ChildItem -LiteralPath $p -Force | Select-Object -First 30 Name,Mode,FullName)
  }
 }
}
$procs=Get-CimInstance Win32_Process | Where-Object {
 $_.CommandLine -and $_.CommandLine -match 'WebAIBridge|17448|server\.js|supervisor-watchdog\.js' -and $_.CommandLine -notmatch 'E:\\manhwa'
} | Select-Object ProcessId,ParentProcessId,Name,ExecutablePath,CommandLine;
[pscustomobject]@{roots=$roots;processes=@($procs)}|ConvertTo-Json -Depth 6 -Compress
